111	// ─── Gitignore helpers ───────────────────────────────────────────────
112	
113	/**
114	 * Check if the gitignore content already has an entry for .agentrack.
115	 * Matches common patterns: /.agentrack/, .agentrack/, /.agentrack, .agentrack
116	 */
117	function gitignoreHasEntry(content: string): boolean {
118	  return content.split("\n").some((rawLine) => {
119	    const line = rawLine.trim();
120	    // Skip comments and empty lines
121	    if (!line || line.startsWith("#")) return false;
122	    return (
123	      line === "/.agentrack/" ||
124	      line === ".agentrack/" ||
125	      line === "/.agentrack" ||
126	      line === ".agentrack"
127	    );
128	  });
129	}
130	
131	/**
132	 * Ensure .gitignore has an entry for .agentrack.
133	 * Appends the entry if missing. Does NOT stage or commit.
134	 * Returns true if an entry was added.
135	 */
136	function ensureGitignoreEntry(cwd: string): boolean {
137	  const gitignorePath = join(cwd, ".gitignore");
138	  if (existsSync(gitignorePath)) {
139	    const content = readFileSync(gitignorePath, "utf-8");
140	    if (gitignoreHasEntry(content)) {
141	      return false;
142	    }
143	    // Append entry (ensure newline before if file doesn't end with one)
144	    const suffix = content.endsWith("\n") ? "" : "\n";
145	    writeFileSync(gitignorePath, `${content}${suffix}/.agentrack/\n`, "utf-8");
146	  } else {
147	    writeFileSync(gitignorePath, "/.agentrack/\n", "utf-8");
148	  }
149	  return true;
150	}
151	
152	// ─── Precondition checks ─────────────────────────────────────────────
153	
154	/**
155	 * Validate preconditions before worktree initialization.
156	 * Throws AgentrackError if any precondition fails.
157	 */
158	function checkPreconditions(cwd: string): void {
159	  // Must be inside a git repo
160	  if (!isGitRepo(cwd)) {
161	    throw new AgentrackError(
162	      ErrorCodes.NOT_A_GIT_REPO.result,
163	      "Not inside a git repository",
164	      ErrorCodes.NOT_A_GIT_REPO.exitCode,
165	    );
166	  }
167	
168	  // .agentrack must not exist as a non-worktree (legacy)
169	  const agentrackPath = join(cwd, WORKTREE_DIR);
170	  if (existsSync(agentrackPath)) {
171	    const stat = statSync(agentrackPath);
172	    if (!stat.isDirectory()) {
173	      throw new AgentrackError(
174	        ErrorCodes.MIGRATION_REQUIRED.result,
175	        ".agentrack exists but is not a directory. Remove it and re-run init.",
176	        ErrorCodes.MIGRATION_REQUIRED.exitCode,
177	      );
178	    }
179	    // Directory exists — if not a worktree, it's a legacy directory
180	    if (!isWorktreeInitialized(cwd)) {
181	      throw new AgentrackError(
182	        ErrorCodes.MIGRATION_REQUIRED.result,
183	        ".agentrack/ exists but is not a git worktree. Remove it manually and re-run init.",
184	        ErrorCodes.MIGRATION_REQUIRED.exitCode,
185	      );
186	    }
187	    // If it IS a valid worktree, caller should handle ALREADY_INITIALIZED
188	  }
189	
190	  // Must not be on the _agentrack branch
191	  const currentBranch = getCurrentBranch(cwd);
192	  if (currentBranch === WORKTREE_BRANCH) {
193	    throw new AgentrackError(
194	      ErrorCodes.INVALID_STATE.result,
195	      "Cannot init: currently on the _agentrack branch. Switch to a code branch first.",
196	      ErrorCodes.INVALID_STATE.exitCode,
197	    );
198	  }
199	}
200	
201	// ─── Public API ──────────────────────────────────────────────────────
202	
203	/**
204	 * Detect which init scenario applies: 'fresh' (no remote branch) or 'join' (remote branch exists).
205	 */
206	export function detectInitScenario(cwd: string): "fresh" | "join" {
207	  try {
208	    const result = gitExec(cwd, ["ls-remote", "--heads", "origin", WORKTREE_BRANCH]);
209	    return result.trim().length > 0 ? "join" : "fresh";
210	  } catch {
211	    // No remote or no connectivity → fresh
212	    return "fresh";
213	  }
214	}
215	
216	/**
217	 * Check if .agentrack/ is a valid git worktree for the _agentrack branch.
218	 */
219	export function isWorktreeInitialized(cwd: string): boolean {
220	  try {
221	    const worktreeList = gitExec(cwd, ["worktree", "list", "--porcelain"]);
222	    const normalizedCwd = resolve(cwd);
223	    const expectedPath = normalize(join(normalizedCwd, WORKTREE_DIR));
224	
225	    return worktreeList.split("\n").some((line) => {
226	      if (!line.startsWith("worktree ")) return false;
227	      const wtPath = line.slice("worktree ".length);
228	      return normalize(wtPath) === expectedPath;
229	    });
230	  } catch {
231	    return false;
232	  }
233	}
234	
235	/**
236	 * Scenario A: create orphan branch with initial data, push, mount worktree.
237	 * Uses git plumbing commands to avoid modifying the working tree.
238	 */
239	export function initFreshWorktree(cwd: string): WorktreeInitResult {
240	  // 1. Create blob objects for initial files
241	  const configBlob = gitHashObject(cwd, `${JSON.stringify(DEFAULT_CONFIG, null, 2)}\n`);
242	  const indexBlob = gitHashObject(cwd, `${JSON.stringify(DEFAULT_INDEX, null, 2)}\n`);
243	  const depsBlob = gitHashObject(cwd, `${JSON.stringify(DEFAULT_DEPENDENCIES, null, 2)}\n`);
244	  const usersBlob = gitHashObject(cwd, `${JSON.stringify(DEFAULT_USERS, null, 2)}\n`);
245	
246	  // 2. Create a tree object referencing these blobs
247	  const treeInput = [
248	    `100644 blob ${configBlob}\tconfig.json`,
249	    `100644 blob ${indexBlob}\tindex.json`,
250	    `100644 blob ${depsBlob}\tdependencies.json`,
251	    `100644 blob ${usersBlob}\tusers.json`,
252	  ].join("\n");
253	  const tree = gitMkTree(cwd, treeInput);
254	
255	  // 3. Create a commit from the tree
256	  const commit = gitCommitTree(cwd, tree, "init _agentrack branch");
257	
258	  // 4. Create the _agentrack branch ref
259	  try {
260	    gitExec(cwd, ["branch", WORKTREE_BRANCH, commit]);
261	  } catch (err) {
262	    // Branch might already exist from a failed previous attempt
263	    const stderr = getGitError(err);
264	    if (stderr.includes("already exists")) {
265	      // Force-update the branch to our new commit
266	      gitExec(cwd, ["branch", "-f", WORKTREE_BRANCH, commit]);
267	    } else {
268	      throw new AgentrackError(
269	        ErrorCodes.INVALID_STATE.result,
270	        `Failed to create branch: ${stderr}`,
271	        ErrorCodes.INVALID_STATE.exitCode,
272	      );
273	    }
274	  }
275	
276	  // 5. Push to remote (if available)
277	  if (hasRemote(cwd)) {
278	    try {
279	      gitExec(cwd, ["push", "-u", "origin", WORKTREE_BRANCH]);
280	    } catch (pushErr) {
281	      const stderr = getGitError(pushErr);
282	      // If push fails because branch already exists remotely, fall back to join
283	      if (
284	        stderr.includes("already exists") ||
285	        stderr.includes("failed to push") ||
286	        stderr.includes("non-fast-forward")
287	      ) {
288	        return initJoinWorktree(cwd);
289	      }
290	      // Network or other errors — proceed with local branch only (warn implicitly)
291	    }
292	  }
293	
294	  // 6. Ensure .gitignore entry and commit the change
295	  const gitignoreAdded = ensureGitignoreEntry(cwd);
296	  if (gitignoreAdded) {
297	    gitExec(cwd, ["add", ".gitignore"]);
298	    gitExec(cwd, ["commit", "-m", "chore: add .agentrack/ to .gitignore"]);
299	  }
300	
301	  // 7. Mount worktree
302	  try {
303	    gitExec(cwd, ["worktree", "add", WORKTREE_DIR, WORKTREE_BRANCH]);
304	  } catch (err) {
305	    const stderr = getGitError(err);
306	    throw new AgentrackError(
307	      ErrorCodes.INVALID_STATE.result,
308	      `Failed to mount worktree: ${stderr}`,
309	      ErrorCodes.INVALID_STATE.exitCode,
310	    );
311	  }
312	
313	  return { scenario: "fresh", path: resolve(cwd, WORKTREE_DIR) };
314	}
315	
316	/**
317	 * Scenario B: fetch remote branch, create tracking branch, mount worktree.
318	 */
319	export function initJoinWorktree(cwd: string): WorktreeInitResult {
320	  // 1. Fetch the remote branch
321	  try {
322	    gitExec(cwd, ["fetch", "origin", WORKTREE_BRANCH]);
323	  } catch (err) {
324	    const stderr = getGitError(err);
325	    throw new AgentrackError(
326	      ErrorCodes.INVALID_STATE.result,
327	      `Failed to fetch remote branch: ${stderr}`,
328	      ErrorCodes.INVALID_STATE.exitCode,
329	    );
330	  }
331	
332	  // 2. Create local tracking branch
333	  try {
334	    gitExec(cwd, ["branch", WORKTREE_BRANCH, `origin/${WORKTREE_BRANCH}`]);
335	  } catch {
336	    // Branch might already exist — force-update to remote ref
337	    try {
338	      gitExec(cwd, ["branch", "-f", WORKTREE_BRANCH, `origin/${WORKTREE_BRANCH}`]);
339	    } catch (err) {
340	      const stderr = getGitError(err);
341	      throw new AgentrackError(
342	        ErrorCodes.INVALID_STATE.result,
343	        `Failed to create tracking branch: ${stderr}`,
344	        ErrorCodes.INVALID_STATE.exitCode,
345	      );
346	    }
347	  }
348	
349	  // 3. Ensure .gitignore entry
350	  ensureGitignoreEntry(cwd);
351	
352	  // 4. Mount worktree
353	  try {
354	    gitExec(cwd, ["worktree", "add", WORKTREE_DIR, WORKTREE_BRANCH]);
355	  } catch (err) {
356	    const stderr = getGitError(err);
357	    throw new AgentrackError(
358	      ErrorCodes.INVALID_STATE.result,
359	      `Failed to mount worktree: ${stderr}`,
360	      ErrorCodes.INVALID_STATE.exitCode,
361	    );
362	  }
363	
364	  return { scenario: "join", path: resolve(cwd, WORKTREE_DIR) };
365	}
366	
367	/**
368	 * Initialize the agentrack worktree. Performs precondition checks, detects the
369	 * scenario, and delegates to the appropriate setup function.
370	 *
371	 * Returns the init result, or throws AgentrackError on failure.
372	 */
373	export function initWorktree(cwd: string): WorktreeInitResult {
374	  // Check if already initialized
375	  if (isWorktreeInitialized(cwd)) {
376	    return { scenario: "already_initialized", path: resolve(cwd, WORKTREE_DIR) };
377	  }
378	
379	  // Validate preconditions (throws on failure)
380	  checkPreconditions(cwd);
381	
382	  // Detect scenario and delegate
383	  const scenario = detectInitScenario(cwd);
384	  if (scenario === "fresh") {
385	    return initFreshWorktree(cwd);
386	  }
387	  return initJoinWorktree(cwd);
388	}
389	
390	/**
391	 * Stage all changes in the worktree and commit them with the given message.
392	 * Used after tracker.init() to persist initial data to the _agentrack branch.
393	 */
394	export function commitWorktreeData(cwd: string, message: string): void {
395	  const worktreeDir = join(cwd, WORKTREE_DIR);
396	  gitExec(worktreeDir, ["add", "-A"]);
397	  try {
398	    gitExec(worktreeDir, ["commit", "-m", message]);
399	  } catch {
400	    // No changes to commit — that's fine (e.g., data already committed)
401	  }
402	}
403	
404	/**
405	 * Stage all changes, auto-commit, and push to remote.
406	 */
407	export function pushWorktree(cwd: string, message?: string): WorktreeSyncResult {
408	  const worktreeDir = join(cwd, WORKTREE_DIR);
409	
410	  // Verify worktree is initialized
411	  if (!isWorktreeInitialized(cwd)) {
412	    throw new AgentrackError(
413	      ErrorCodes.NOT_INITIALIZED.result,
414	      "Agentrack not initialized. Run `agt init` first.",
415	      ErrorCodes.NOT_INITIALIZED.exitCode,
416	    );
417	  }
418	
419	  // Stage all changes
420	  gitExec(worktreeDir, ["add", "-A"]);
421	
422	  // Check for staged changes
423	  let hasStagedChanges = false;
424	  try {
425	    gitExec(worktreeDir, ["diff", "--cached", "--quiet"]);
426	    // Exit code 0 = no diff = no staged changes
427	  } catch {
428	    // Exit code 1 = there are staged changes
429	    hasStagedChanges = true;
430	  }
431	
432	  if (hasStagedChanges) {
433	    // Commit staged changes
434	    const commitMessage =
435	      message || `sync: ${new Date().toISOString()}`;
436	    try {
437	      gitExec(worktreeDir, ["commit", "-m", commitMessage]);
438	    } catch (err) {
439	      const stderr = getGitError(err);
440	      throw new AgentrackError(
441	        ErrorCodes.PUSH_FAILED.result,
442	        `git commit failed: ${stderr}`,
443	        ErrorCodes.PUSH_FAILED.exitCode,
444	      );
445	    }
446	  }
447	
448	  // Check if there's anything to push
449	  let hasUnpushedCommits = false;
450	  try {
451	    const count = gitExec(worktreeDir, ["rev-list", "--count", "@{upstream}..HEAD"]).trim();
452	    hasUnpushedCommits = parseInt(count, 10) > 0;
453	  } catch {
454	    // No upstream set — means we need to push
455	    hasUnpushedCommits = true;
456	  }
457	
458	  if (!hasStagedChanges && !hasUnpushedCommits) {
459	    return { synced: false, message: "No changes to sync" };
460	  }
461	
462	  // Push to remote
463	  if (hasRemote(cwd)) {
464	    try {
465	      gitExec(worktreeDir, ["push"]);
466	    } catch (err) {
467	      const stderr = getGitError(err);
468	      throw new AgentrackError(
469	        ErrorCodes.PUSH_FAILED.result,
470	        `git push failed: ${stderr}`,
471	        ErrorCodes.PUSH_FAILED.exitCode,
472	      );
473	    }
474	  }
475	
476	  return {
477	    synced: true,
478	    commitCount: hasStagedChanges ? 1 : 0,
479	  };
480	}
481	
482	/**
483	 * Pull latest from remote into the worktree.
484	 */
485	export function pullWorktree(cwd: string): WorktreePullResult {
486	  const worktreeDir = join(cwd, WORKTREE_DIR);
487	
488	  // Verify worktree is initialized
489	  if (!isWorktreeInitialized(cwd)) {
490	    throw new AgentrackError(
491	      ErrorCodes.NOT_INITIALIZED.result,
492	      "Agentrack not initialized. Run `agt init` first.",
493	      ErrorCodes.NOT_INITIALIZED.exitCode,
494	    );
495	  }
496	
497	  try {
498	    const output = gitExec(worktreeDir, ["pull"]);
499	    // "Already up to date." means no updates
500	    const updated = !output.includes("Already up to date");
501	    return { updated };
502	  } catch (err) {
503	    const stderr = getGitError(err);
504	    throw new AgentrackError(
505	      ErrorCodes.PULL_FAILED.result,
506	      `git pull failed: ${stderr}`,
507	      ErrorCodes.PULL_FAILED.exitCode,
508	    );
509	  }
510	}
